'    ''f?p='' || :APP_ID || '':200:'' || :APP_SESSION || ''::NO:::'' AS CARD_LINK',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Storage Dashboard''     AS CARD_TITLE,',
'    ''Monitor warehouse levels'' AS CARD_DESC,',
'    ''fa fa-cubes''             AS CARD_ICON,   -- Added ''fa ''',
'    ''f?p='' || :APP_ID || '':300:'' || :APP_SESSION || ''::NO:::'' AS CARD_LINK',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    ''Disposal Dashboard''    AS CARD_TITLE,',
'    ''Manage waste removal''  AS CARD_DESC,',
'    ''fa fa-truck''           AS CARD_ICON,   -- Added ''fa ''',
'    ''f?p='' || :APP_ID || '':400:'' || :APP_SESSION || ''::NO:::'' AS CARD_LINK',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    ''User Profile''          AS CARD_TITLE,',
'    ''Manage account & info'' AS CARD_DESC,',
'    ''fa fa-user-circle''     AS CARD_ICON,   -- Added ''fa ''',
'    ''f?p='' || :APP_ID || '':110:'' || :APP_SESSION || ''::NO:::'' AS CARD_LINK',
