wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(8786875153701183221)
,p_plug_name=>'System Overview'
,p_static_id=>'system-overview'
,p_title=>'Overview'
,p_region_name=>'overview-cards'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleB'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- Card 1: Total Waste Today',
'-- Sums quantity from WASTE_RECORD for the current day',
'SELECT ',
'    ''Total Waste Today''                  AS LABEL,',
'    (SELECT NVL(SUM(WASTE_QUANTITY), 0) || '' kg'' ',
'     FROM WASTE_RECORD ',
'     WHERE TRUNC(WASTE_GENERATED_DATE) = TRUNC(SYSDATE)) AS VALUE,',
'    ''fa fa-recycle''                         AS ICON,',
'    ''u-color-9''                          AS COLOR -- Green',
'FROM DUAL',
'',
'UNION ALL',
'',
'-- Card 2: Storage Usage',
'-- Uses your View (VW_STORAGE_RECORD_DETAILED) to get the average fill level',
'SELECT ',
'    ''Avg. Storage Level''                 AS LABEL,',
'    (SELECT NVL(ROUND(AVG(STORAGE_FILL_LEVEL), 0), 0) || ''%'' ',
'     FROM VW_STORAGE_RECORD_DETAILED)    AS VALUE,',
'    ''fa fa-industry''                        AS ICON,',
'    ''u-color-12''                         AS COLOR -- Red/Orange',
'FROM DUAL',
'',
'UNION ALL',
'',
'-- Card 3: Pending Disposals',
'-- Counts ''Scheduled'' items in DISPOSAL_SCHEDULE',
'SELECT ',
'    ''Pending Disposals''                  AS LABEL,',
'    (SELECT TO_CHAR(COUNT(*)) ',
'     FROM DISPOSAL_SCHEDULE ',
'     WHERE DISPOSAL_STATUS = ''Scheduled'') AS VALUE, -- Matched to your CHECK constraint',
'    ''fa fa-truck''                           AS ICON,',
'    ''u-color-4''                          AS COLOR -- Blue',
'FROM DUAL',
'',
'UNION ALL',
'',
'-- Card 4: Active Users',
'-- Counts ''Active'' users in APP_USER',
'SELECT ',
'    ''Active Users''                       AS LABEL,',
'    (SELECT TO_CHAR(COUNT(*)) ',
'     FROM APP_USER ',
'     WHERE USER_STATUS = ''Active'')       AS VALUE,',
'    ''fa fa-users''                           AS ICON,',
'    ''u-color-1''                          AS COLOR -- Teal',
'FROM DUAL'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_plug_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div style="border-bottom: 1px solid #ddd; padding-bottom: 10px; margin-bottom: 15px;">',
'    <span style="font-size: 14px; color: #134f45;">',
'       <i class="fa fa-info-circle"></i> Overview of today''s operational status',
'    </span>',
'</div>'))
