wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(3116185662374748635)
,p_validation_name=>'Check Old Password Correct'
,p_static_id=>'check-old-password-correct'
,p_validation_sequence=>130
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_current_pwd VARCHAR2(255);',
'BEGIN',
'    IF :P111_NEW_PASSWORD IS NOT NULL THEN',
'        SELECT USER_PASSWORD INTO v_current_pwd ',
'        FROM APP_USER WHERE USER_ID = :P111_USER_ID;',
'        ',
'        IF :P111_OLD_PASSWORD != v_current_pwd THEN',
'            RETURN ''The Old Password you entered is incorrect.'';',
'        END IF;',
'    END IF;',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_imp.id(3116185396131748632)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20251224083155Z')
,p_updated_on=>wwv_flow_imp.dz('20251224083155Z')
,p_created_by=>'JIAHONG'
,p_updated_by=>'JIAHONG'
);
