wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(130571959253927802606)
,p_validation_name=>'New Password Must Differ from Old Password'
,p_static_id=>'new-password-must-differ-from-old-password'
,p_validation_sequence=>150
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    IF :P111_NEW_PASSWORD IS NOT NULL OR :P111_CONFIRM_PASSWORD IS NOT NULL THEN',
'        DECLARE',
'            v_new_pwd VARCHAR2(100);',
'        BEGIN',
'            v_new_pwd := NVL(:P111_NEW_PASSWORD, :P111_CONFIRM_PASSWORD);',
'            ',
'            RETURN v_new_pwd != :P111_OLD_PASSWORD;',
'        END;',
'    END IF;',
'    ',
'    RETURN TRUE;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'New password must be different from your current password.'
,p_validation_condition=>'P111_NEW_PASSWORD'
,p_validation_condition_type=>'ITEM_IS_NOT_NULL'
,p_when_button_pressed=>wwv_flow_imp.id(3060956907916706422)
