 p_id=>200
,p_name=>'Waste Generation Dashboard'
,p_alias=>'WASTE-GENERATION-DASHBOARD'
,p_step_title=>'Waste Generation Dashboard'
,p_autocomplete_on_off=>'OFF'
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'/* --- 1. CARD CONTAINER --- */',
'/* Target the card wrapper */',
'.kpi-card-float .a-Card {',
'    position: relative; /* Essential for the ''sticker'' to attach */',
'    background-color: #ffffff !important;',
'    border-radius: 8px !important;',
'    border: 1px solid #dcdcdc !important; /* Subtle Grey Outline */',
'    overflow: hidden;   /* Ensures the colored strip respects rounded corners */',
'    transition: transform 0.2s ease, box-shadow 0.2s ease;',
'    ',
'    /* Layout Fixes */',
'    display: flex;',
'    flex-direction: column;',
'    justify-content: center;',
'    min-height: 140px; /* Force equal height */',
'}',
'',
'/* Hover Animation */',
'.kpi-card-float .a-Card:hover {',
'    transform: translateY(-5px);',
'    box-shadow: 0 15px 30px rgba(0,0,0,0.1);',
'    cursor: pointer;',
'}',
'',
'/* --- 2. THE COLORED "STICKER" (The Fix) --- */',
'/* We use ::before to draw a 6px wide strip on the left */',
'',
'/* BLUE */',
'.card-blue .a-Card::before, .card-blue.a-Card::before {',
'    content: "";',
'    position: absolute;',
'    left: 0; top: 0; bottom: 0;',
'    width: 6px;',
'    background-color: #1E88E5;',
'    z-index: 2; /* Sit on top of card background */',
'}',
'/* BLUE ICON */',
'.card-blue .a-Card-icon { color: #1E88E5; background: #E3F2FD; }',
'',
'',
'/* GREEN (Leaf) */',
'.card-green .a-Card::before, .card-green.a-Card::before {',
'    content: "";',
'    position: absolute;',
'    left: 0; top: 0; bottom: 0;',
'    width: 6px;',
'    background-color: #7CB342;',
'    z-index: 2;',
'}',
'/* GREEN ICON */',
'.card-green .a-Card-icon { color: #7CB342; background: #F1F8E9; }',
'',
'',
'/* ORANGE */',
'.card-orange .a-Card::before, .card-orange.a-Card::before {',
'    content: "";',
'    position: absolute;',
'    left: 0; top: 0; bottom: 0;',
'    width: 6px;',
'    background-color: #FB8C00;',
'    z-index: 2;',
'}',
'/* ORANGE ICON */',
'.card-orange .a-Card-icon { color: #FB8C00; background: #FFF3E0; }',
'',
'',
'/* PURPLE */',
'.card-purple .a-Card::before, .card-purple.a-Card::before {',
'    content: "";',
'    position: absolute;',
'    left: 0; top: 0; bottom: 0;',
'    width: 6px;',
'    background-color: #8E24AA;',
'    z-index: 2;',
'}',
'/* PURPLE ICON */',
'.card-purple .a-Card-icon { color: #8E24AA; background: #F3E5F5; }',
'',
'',
'/* --- 3. TYPOGRAPHY & LAYOUT FIXES --- */',
'',
'/* Fix the Header (Icon + Title) */',
'.a-Card-header {',
'    justify-content: center !important;',
'    text-align: center;',
'    border-bottom: none;',
'    padding-bottom: 5px;',
'    position: relative;',
'    z-index: 3; /* Ensure text sits above any background layers */',
'}',
'',
'/* Fix the Body */',
'.a-Card-body {',
'    padding: 0 10px 15px 10px;',
'    z-index: 3;',
'}',
'',
'.kpi-card-content {',
'    text-align: center;',
'    width: 100%;',
'}',
'',
'/* BIG NUMBERS */',
'.kpi-value-NUMBER {',
'    font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;',
'    font-size: 1.5rem;',
'    font-weight: 600;',
'    color: #2d2d2d;',
'    line-height: 1;',
'    letter-spacing: -0.5px;',
'}',
'',
'/* TEXT */',
'.kpi-value-TEXT {',
'    font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;',
'    font-size: 1.0rem;',
'    font-weight: 600;',
'    color: #555;',
'    line-height: 1.4;',
'    word-wrap: break-word;',
'}'))
