 p_id=>wwv_flow_imp.id(7775090981751425334)
,p_plug_name=>'KPI Metrics'
,p_static_id=>'kpi-metrics'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_escape_on_http_output=>'N'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH USER_PERM AS (',
'    SELECT CASE ',
'        WHEN USER_ROLE IN (''Administrator'', ''Waste Management Staff'') THEN 1 ',
'        ELSE 0 ',
'    END AS IS_AUTHORIZED',
'    FROM APP_USER ',
'    WHERE USER_ID = :APP_CURRENT_USER_ID',
')',
'SELECT ',
'    1 AS SORT_ORDER,',
'    ''Recent Records (24h)'' AS CARD_TITLE,',
'    TO_CHAR((SELECT COUNT(*) FROM VW_WASTE_RECORD WHERE HOURS_OLD <= 24)) AS CARD_VALUE,',
'    ''NUMBER'' AS VALUE_TYPE,  -- Tells CSS to make this Big',
'    ''fa fa-clock-o'' AS CARD_ICON,',
'    ''card-blue'' AS STYLE_CLASS,',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_PERM) = 1 THEN ',
'        ''f?p='' || :APP_ID || '':201:'' || :APP_SESSION ',
'    ELSE NULL END AS LINK_URL',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    2,',
'    ''Top Source (Weekly)'',',
'    NVL((SELECT SOURCE_NAME FROM (',
'            SELECT WS.SOURCE_NAME, COUNT(*) as CNT',
'            FROM WASTE_RECORD WR',
'            JOIN WASTE_SOURCE WS ON WR.SOURCE_ID = WS.SOURCE_ID',
'            WHERE WR.WASTE_GENERATED_DATE >= SYSDATE - 7',
'            GROUP BY WS.SOURCE_NAME',
'            ORDER BY CNT DESC',
'         ) WHERE ROWNUM = 1), ''No Data'') AS CARD_VALUE,',
'    ''TEXT'' AS VALUE_TYPE,  -- Tells CSS to make this Smaller/Readable',
'    ''fa fa-industry'',',
'    ''card-green'',',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_PERM) = 1 THEN ',
'        ''f?p='' || :APP_ID || '':205:'' || :APP_SESSION ',
'    ELSE NULL END',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    3,',
'    ''Total Waste Sources'',',
'    TO_CHAR((SELECT COUNT(*) FROM WASTE_SOURCE)) AS CARD_VALUE,',
'    ''NUMBER'' AS VALUE_TYPE,',
'    ''fa fa-building'',',
'    ''card-orange'',',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_PERM) = 1 THEN ',
'        ''f?p='' || :APP_ID || '':205:'' || :APP_SESSION ',
'    ELSE NULL END',
'FROM DUAL',
'',
'UNION ALL',
'',
'SELECT ',
'    4,',
'    ''Waste Types'',',
'    TO_CHAR((SELECT COUNT(*) FROM WASTE_TYPE)) AS CARD_VALUE,',
'    ''NUMBER'' AS VALUE_TYPE,',
'    ''fa fa-tags'',',
'    ''card-purple'',',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_PERM) = 1 THEN ',
'        ''f?p='' || :APP_ID || '':204:'' || :APP_SESSION ',
'    ELSE NULL END',
'FROM DUAL'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
