'SELECT ',
'    s.SOURCE_NAME                as LABEL, ',
'    COUNT(r.WASTE_RECORD_ID)     as VALUE,',
'    CASE MOD(ROW_NUMBER() OVER (ORDER BY COUNT(r.WASTE_RECORD_ID) DESC), 5)',
'        WHEN 1 THEN ''#E95F59''  -- Red    (1st Place)',
'        WHEN 2 THEN ''#F9D856''  -- Yellow (2nd Place)',
'        WHEN 3 THEN ''#5AC96B''  -- Green  (3rd Place)',
'        WHEN 4 THEN ''#2D76B5''  -- Blue   (4th Place)',
'        ELSE        ''#8F6AD4''  -- Purple (5th Place)',
