wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3761738617817246763)
,p_plug_name=>'Waste Record IR'
,p_static_id=>'waste-record-ir'
,p_title=>'Waste Record'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>40
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    WASTE_RECORD_ID,',
'    WASTE_NAME,',
'    WASTE_QUANTITY || '' '' || WASTE_UNIT AS "Current Quantity",',
'    WASTE_GENERATED_DATE AS "Generation Date",',
'    WASTE_RECORD_CREATED_DATE,',
'    WASTE_RECORD_REMARK,',
'    USER_ID,',
'    SOURCE_ID,',
'    WASTE_TYPE_ID,',
'    ',
'    USER_FULL_NAME,',
'    USER_ROLE,',
'    WASTE_TYPE_NAME,',
'    WASTE_TYPE_HAZARD_CLASS AS "Hazard Class",',
'    SOURCE_NAME,',
'    SOURCE_HAZARD_LEVEL,',
'    '' '' AS EDIT_LINK,',
'',
'    -- 1. ICON COLOR LOGIC',
'    CASE ',
'        -- If older than 24 hours -> Disabled (Grey/Red)',
'        WHEN HOURS_OLD >= 24 THEN ''u-danger-text''',
'        ',
'        -- If Current User is Creator -> Enabled (Blue)',
'        WHEN USER_ID = :APP_CURRENT_USER_ID THEN ''u-info-text''',
'        ',
'        -- If Current User is Admin -> Enabled (Blue)',
'        WHEN (SELECT USER_ROLE FROM APP_USER WHERE USER_ID = :APP_CURRENT_USER_ID) = ''Administrator'' THEN ''u-info-text''',
'        ',
'        -- Otherwise (Not Creator, Not Admin) -> Disabled',
'        ELSE ''u-danger-text''',
'    END as ICON_COLOR,',
'',
'    -- 2. EDIT STYLE LOGIC (The Clickability)',
'    CASE ',
'        -- PRIORITY 1: TIME LIMIT',
'        -- If record is older than 24 hours, NO ONE can edit.',
'        WHEN HOURS_OLD >= 24 ',
'            THEN ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'',
'        -- PRIORITY 2: PERMISSIONS (If time is < 24h)',
'        -- Allow if: User is Creator OR User is Admin.',
'        -- Therefore, DISABLE if: User is NOT Creator AND User is NOT Admin.',
'        WHEN USER_ID != :APP_CURRENT_USER_ID ',
'             AND (SELECT USER_ROLE FROM APP_USER WHERE USER_ID = :APP_CURRENT_USER_ID) != ''Administrator''',
'            THEN ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'        ',
'        -- ELSE: Record is new (<24h) AND User is either Creator or Admin -> Allow Edit',
'        ELSE '''' ',
'    END as EDIT_STYLE',
'FROM VW_WASTE_RECORD',
'WHERE (:P201_WASTE_TYPE_ID IS NULL ',
'    OR INSTR('':'' || :P201_WASTE_TYPE_ID || '':'', '':'' || WASTE_TYPE_ID || '':'') > 0)',
'AND (:P201_SOURCE_ID IS NULL ',
'    OR INSTR('':'' || :P201_SOURCE_ID || '':'', '':'' || SOURCE_ID || '':'') > 0)',
'AND (:P201_USER_ID IS NULL ',
'    OR INSTR('':'' || :P201_USER_ID || '':'', '':'' || USER_ID || '':'') > 0)',
'AND (:P201_WASTE_GENERATED_DATE IS NULL ',
'         OR (WASTE_GENERATED_DATE >= TO_DATE(REGEXP_SUBSTR(:P201_WASTE_GENERATED_DATE, ''^[^|]+''), ''YYYYMMDDHH24MISS'')',
'             AND (REGEXP_SUBSTR(:P201_WASTE_GENERATED_DATE, ''[^|]+$'') IS NULL ',
'                  OR WASTE_GENERATED_DATE <= TO_DATE(REGEXP_SUBSTR(:P201_WASTE_GENERATED_DATE, ''[^|]+$''), ''YYYYMMDDHH24MISS''))))',
'ORDER BY WASTE_RECORD_ID DESC'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header=>'Waste Record'
,p_prn_page_header_font_color=>'#000000'
