wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3836865653441937237)
,p_plug_name=>'Waste Source IR'
,p_static_id=>'waste-source-ir'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>50
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT SOURCE_ID,',
'       SOURCE_NAME,',
'       SOURCE_DESCRIPTION,',
'       CASE SOURCE_HAZARD_LEVEL',
'           WHEN ''High''   THEN ''<span style="color:#D9534F; font-weight:bold;"><span class="fa fa-exclamation-triangle" aria-hidden="true"></span> High</span>''',
'           WHEN ''Medium'' THEN ''<span style="color:#F0AD4E; font-weight:bold;"><span class="fa fa-exclamation-circle" aria-hidden="true"></span> Medium</span>''',
'           WHEN ''Low''    THEN ''<span style="color:#5BC0DE; font-weight:bold;"><span class="fa fa-shield" aria-hidden="true"></span> Low</span>''',
'           WHEN ''None''   THEN ''<span style="color:#5CB85C; font-weight:bold;"><span class="fa fa-leaf" aria-hidden="true"></span> None</span>''',
'           ELSE SOURCE_HAZARD_LEVEL',
'       END AS SOURCE_HAZARD_LEVEL,',
'       '' '' AS EDIT_LINK',
'  FROM WASTE_SOURCE',
' WHERE (:P205_SOURCE_HAZARD_LEVEL IS NULL ',
'        OR INSTR('':'' || :P205_SOURCE_HAZARD_LEVEL || '':'', '':'' || SOURCE_HAZARD_LEVEL || '':'') > 0)',
' ORDER BY SOURCE_ID ASC'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_page_header=>'Waste Source'
,p_ai_enabled=>false
