wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(3843096608881405425)
,p_chart_id=>wwv_flow_imp.id(3843096538900405424)
,p_static_id=>'series'
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    CATEGORY as FILL_CATEGORY,',
'    COUNT(*) AS CONTAINER_COUNT,',
'    CASE ',
'        WHEN CATEGORY = ''Critical (95%+)''    THEN ''#FF3B30'' -- Red',
'        WHEN CATEGORY = ''Warning (80-94%)''   THEN ''#FF9500'' -- Orange',
'        WHEN CATEGORY = ''Half Full (50-79%)'' THEN ''#34AADC'' -- Blue',
'        ELSE ''#4CD964'' -- Green',
'    END AS COLOR,',
'    CASE ',
'        WHEN CATEGORY = ''Critical (95%+)''    THEN 1',
'        WHEN CATEGORY = ''Warning (80-94%)''   THEN 2',
'        WHEN CATEGORY = ''Half Full (50-79%)'' THEN 3',
'        ELSE 4',
'    END AS SORT_ORDER',
'FROM (',
'    SELECT ',
'        CASE ',
'            WHEN (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 95 THEN ''Critical (95%+)''',
'            WHEN (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 80 THEN ''Warning (80-94%)''',
'            WHEN (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 50 THEN ''Half Full (50-79%)''',
'            ELSE ''Low (<50%)''',
'        END AS CATEGORY',
'    FROM (',
'        -- 1. Find the latest record ID for each container',
'        SELECT STORAGE_CONTAINER_ID, MAX(STORAGE_RECORD_ID) AS LATEST_RECORD',
'        FROM STORAGE_RECORD',
'        GROUP BY STORAGE_CONTAINER_ID',
'    ) latest',
'    -- 2. Join Storage Record to get Quantity',
'    JOIN STORAGE_RECORD sr ON latest.LATEST_RECORD = sr.STORAGE_RECORD_ID',
'    -- 3. Join Container to get Capacity (Required for %)',
'    JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'    -- 4. Left Join Schedule to check Status',
'    LEFT JOIN DISPOSAL_SCHEDULE ds ON sr.STORAGE_RECORD_ID = ds.STORAGE_RECORD_ID',
'    ',
'    -- 5. FILTER: Keep everything EXCEPT ''Completed''',
'    -- This keeps ''Scheduled'' and containers with NO schedule (NULL)',
'    WHERE (ds.DISPOSAL_STATUS != ''Completed'' OR ds.DISPOSAL_STATUS IS NULL)',
')',
'GROUP BY CATEGORY',
'ORDER BY SORT_ORDER;'))
,p_items_value_column_name=>'CONTAINER_COUNT'
,p_items_label_column_name=>'FILL_CATEGORY'
,p_color=>'&COLOR.'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
,p_threshold_display=>'onIndicator'
,p_created_on=>wwv_flow_imp.dz('20251227110531Z')
,p_updated_on=>wwv_flow_imp.dz('20260115174720Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(3843096905686405428)
,p_name=>'High Fill Alerts'
,p_static_id=>'high-fill-alerts'
,p_title=>'Container Alerts'
,p_template=>4072358936313175081
,p_display_sequence=>30
,p_region_template_options=>'t-Region--scrollBody'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    ''Container: '' || sc.STORAGE_CONTAINER_CODE AS alert_title,',
'    ',
'    -- Message',
'    CASE ',
'        WHEN sc.STORAGE_CONTAINER_STATUS IN (''Out of Service'', ''Damaged'') THEN ',
'            ''CRITICAL: Container is '' || sc.STORAGE_CONTAINER_STATUS || '' and unavailable.''',
'        ELSE ',
'            ''Warning: '' || wt.WASTE_TYPE_NAME || '' at '' || sl.STORAGE_LOCATION_NAME || ',
'            '' has reached '' || ROUND(NVL(sr.STORAGE_CURRENT_QUANTITY, 0) / sc.STORAGE_CONTAINER_CAPACITY * 100, 0) || ''% fill.''',
'    END AS alert_desc,',
'',
'    -- COLOR FIX: Change ''critical'' to ''danger'' to activate the Red color',
'    CASE ',
'        WHEN sc.STORAGE_CONTAINER_STATUS IN (''Out of Service'', ''Damaged'') THEN ''danger'' ',
'        ELSE ''warning'' ',
'    END AS alert_type, ',
'',
'    -- Icon',
'    CASE ',
'        WHEN sc.STORAGE_CONTAINER_STATUS IN (''Out of Service'', ''Damaged'') THEN ''fa-ban''',
'        ELSE ''fa-exclamation-triangle''',
'    END AS alert_icon,',
'',
'    CAST(NULL AS VARCHAR2(1)) AS alert_action ',
'',
'FROM STORAGE_CONTAINER sc',
'JOIN STORAGE_LOCATION sl ON sc.STORAGE_LOCATION_ID = sl.STORAGE_LOCATION_ID',
'JOIN WASTE_TYPE wt ON sc.WASTE_TYPE_ID = wt.WASTE_TYPE_ID',
'LEFT JOIN STORAGE_RECORD sr ON sc.STORAGE_CONTAINER_ID = sr.STORAGE_CONTAINER_ID ',
'    AND sr.STORAGE_RECORD_ID IN (',
'        SELECT MAX(STORAGE_RECORD_ID) FROM STORAGE_RECORD GROUP BY STORAGE_CONTAINER_ID',
'    )',
'',
'WHERE ',
'    UPPER(sc.STORAGE_CONTAINER_STATUS) IN (''OUT OF SERVICE'', ''DAMAGED'')',
'    OR ',
'    (NVL(sr.STORAGE_CURRENT_QUANTITY, 0) / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 80',
'',
'ORDER BY ',
'    CASE WHEN UPPER(sc.STORAGE_CONTAINER_STATUS) IN (''OUT OF SERVICE'', ''DAMAGED'') THEN 1 ELSE 2 END,',
'    (NVL(sr.STORAGE_CURRENT_QUANTITY, 0) / sc.STORAGE_CONTAINER_CAPACITY * 100) DESC',
'FETCH FIRST 10 ROWS ONLY;'))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT 1',
'FROM vw_storage_alert_for_disposal'))
,p_display_condition_type=>'EXISTS'
,p_ajax_enabled=>'Y'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>2882902941739462796
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
