wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3843096250715405421)
,p_plug_name=>'Storage Overview'
,p_static_id=>'storage-overview'
,p_region_name=>'overview-cards'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH STORAGE_AUTH AS (',
'    SELECT CASE ',
'        WHEN EXISTS (',
'            SELECT 1 ',
'            FROM APP_USER ',
'            WHERE USERNAME = :APP_USER ',
'            AND USER_ROLE IN (''Administrator'', ''Storage Staff'') ',
'        ) THEN ''Y'' ',
'        ELSE ''N'' ',
'    END AS IS_AUTHORIZED',
'    FROM DUAL',
')',
'',
'/* CARD 1: TOTAL CONTAINERS */',
'SELECT ',
'    ''Total Containers'' AS CARD_TITLE,',
'    ',
'    -- FORMATTED VALUE (To match your Disposal Dashboard style) --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) FROM STORAGE_CONTAINER)',
'    || ''</span>''       AS CARD_VALUE,',
'    ',
'    ''fa fa-cubes''      AS CARD_ICON,',
'    ''u-color-1''        AS CARD_COLOR,',
'    ',
'    -- CONDITIONAL LINK --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':303:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    -- CONDITIONAL CLASS --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''my-hover-card'' ',
'         ELSE ''my-locked-card'' ',
'    END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 2: CRITICAL (>80%) */',
'SELECT ',
'    ''Critical (>80%)''  AS CARD_TITLE,',
'    ',
'    -- FORMATTED VALUE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) ',
'        FROM STORAGE_RECORD sr',
'        JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'        WHERE sr.STORAGE_RECORD_ID IN (',
'            SELECT MAX(STORAGE_RECORD_ID) FROM STORAGE_RECORD GROUP BY STORAGE_CONTAINER_ID',
'        ) ',
'        AND (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 80)',
'    || ''</span>''       AS CARD_VALUE,',
'',
'    ''fa fa-exclamation-triangle'' AS CARD_ICON,',
'    ''u-color-9''        AS CARD_COLOR,',
'    ',
'    -- CONDITIONAL LINK --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':301:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    -- CONDITIONAL CLASS --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''my-hover-card'' ',
'         ELSE ''my-locked-card'' ',
'    END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 3: ADDABLE CONTAINERS (AVAILABLE CAPACITY) */',
'SELECT ',
'    ''Addable Containers'' AS CARD_TITLE,',
'    ',
'    -- FORMATTED VALUE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT NVL(SUM(sl.STORAGE_LOCATION_CAPACITY) - COUNT(sc.STORAGE_CONTAINER_ID), 0)',
'        FROM STORAGE_LOCATION sl ',
'        LEFT JOIN STORAGE_CONTAINER sc ON sl.STORAGE_LOCATION_ID = sc.STORAGE_LOCATION_ID)',
'    || ''</span>''       AS CARD_VALUE,',
'',
'    ''fa fa-check-circle'' AS CARD_ICON,',
'    ''u-color-3''        AS CARD_COLOR,',
'    ',
'    -- CONDITIONAL LINK --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':305:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    -- CONDITIONAL CLASS --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''my-hover-card'' ',
'         ELSE ''my-locked-card'' ',
'    END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 4: SCHEDULED PICKUPS */',
'SELECT ',
'    ''Scheduled Pickups'' AS CARD_TITLE,',
'    ',
'    -- FORMATTED VALUE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) FROM DISPOSAL_SCHEDULE WHERE DISPOSAL_STATUS = ''Scheduled'')',
'    || ''</span>''       AS CARD_VALUE,',
'',
'    ''fa fa-truck''      AS CARD_ICON,',
'    ''u-color-5''        AS CARD_COLOR,',
'    ',
'    -- CONDITIONAL LINK --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':301:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    -- CONDITIONAL CLASS --',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM STORAGE_AUTH) = ''Y'' ',
'         THEN ''my-hover-card'' ',
'         ELSE ''my-locked-card'' ',
'    END AS CARD_CLASS',
'FROM DUAL;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20251227104058Z')
,p_updated_on=>wwv_flow_imp.dz('20260122084206Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
