wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3865287256412167301)
,p_plug_name=>'Storage Record IR (based on View)'
,p_static_id=>'storage-record-ir-based-on-view'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'       STORAGE_RECORD_ID,',
'       STORAGE_DATE,',
'       STORAGE_RECORD_CREATED_DATE,',
'       STORAGE_CURRENT_QUANTITY || '' '' || STORAGE_CONTAINER_UNIT AS "Current Quantity",',
'       STORAGE_FILL_LEVEL || ''%'',',
'       STORAGE_RECORD_DESCRIPTION,',
'       USER_ID,',
'       STORAGE_CONTAINER_ID,',
'       ',
'       -- NEW STATUS LOGIC (Replaces plain DISPOSAL_STATUS)',
'       CASE ',
'           -- 1. COMPLETED',
'           WHEN DISPOSAL_STATUS = ''Completed'' THEN ',
'                ''<span style="color:#5CB85C; font-weight:bold;"><span class="fa fa-check-circle" aria-hidden="true"></span> Completed</span>''',
'           ',
'           -- 2. SCHEDULED',
'           WHEN DISPOSAL_STATUS = ''Scheduled'' THEN ',
'                ''<span style="color:#F0AD4E; font-weight:bold;"><span class="fa fa-clock-o" aria-hidden="true"></span> Scheduled</span>''',
'           ',
'           -- 3. NOT SCHEDULED (CRITICAL - Over 80%)',
'           WHEN DISPOSAL_STATUS = ''Not Scheduled'' AND STORAGE_FILL_LEVEL >= 80 THEN ',
'                ''<span style="color:#D9534F; font-weight:bold;"><span class="fa fa-exclamation-triangle" aria-hidden="true"></span> Alert: Not Scheduled</span>''',
'',
'           -- 4. NOT SCHEDULED (NORMAL - Under 80%)',
'           -- Renamed to "Accumulating" to prevent confusion',
'           WHEN DISPOSAL_STATUS = ''Not Scheduled'' AND STORAGE_FILL_LEVEL < 80 THEN ',
'                ''<span style="color:#5BC0DE; font-weight:bold;"><span class="fa fa-battery-half" aria-hidden="true"></span> Accumulating</span>''',
'           ',
'           ELSE DISPOSAL_STATUS ',
'       END AS DISPOSAL_STATUS,',
'',
'       HOURS_OLD,',
'       USER_FULL_NAME,',
'       USER_ROLE,',
'       STORAGE_CONTAINER_CODE,',
'       STORAGE_CONTAINER_CAPACITY,',
'       STORAGE_CONTAINER_STATUS,',
'       STORAGE_LOCATION_NAME,',
'       STORAGE_LOCATION_STATUS,',
'       WASTE_TYPE_NAME,',
'       WASTE_TYPE_HAZARD_CLASS,',
'       FILL_STATUS,',
'       '' '' AS EDIT_LINK,',
'',
'       -- 1. ICON COLOR LOGIC (Your existing logic)',
'       CASE ',
'           -- Priority 0: SYSTEM Lock',
'           WHEN USER_ID = ''SYS0001'' THEN ''u-danger-text''',
'',
'           -- Priority 1: Disposal Status',
'           WHEN DISPOSAL_STATUS IN (''Scheduled'', ''Completed'') THEN ''u-danger-text''',
'',
'           -- Priority 2 : Historical Record Check',
'           WHEN (SELECT COUNT(*) ',
'                 FROM STORAGE_RECORD newer_rec ',
'                 WHERE newer_rec.STORAGE_CONTAINER_ID = VW_STORAGE_RECORD_DETAILED.STORAGE_CONTAINER_ID ',
'                   AND TRUNC(newer_rec.STORAGE_DATE) > TRUNC(VW_STORAGE_RECORD_DETAILED.STORAGE_DATE)',
'                ) > 0 THEN ''u-danger-text''',
'',
'           -- Priority 3: Time Limit',
'           WHEN HOURS_OLD >= 24 THEN ''u-danger-text''',
'           ',
'           -- Priority 4: Permissions',
'           WHEN USER_ID = :APP_CURRENT_USER_ID THEN ''u-info-text''',
'           WHEN (SELECT USER_ROLE FROM APP_USER WHERE USER_ID = :APP_CURRENT_USER_ID) = ''Administrator'' THEN ''u-info-text''',
'           ELSE ''u-danger-text''',
'       END as ICON_COLOR,',
'',
'       -- 2. EDIT STYLE LOGIC (Your existing logic)',
'       CASE ',
'           WHEN USER_ID = ''SYS0001'' ',
'               THEN ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'           WHEN DISPOSAL_STATUS IN (''Scheduled'', ''Completed'') ',
'               THEN ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'           WHEN (SELECT COUNT(*) ',
'                 FROM STORAGE_RECORD newer_rec ',
'                 WHERE newer_rec.STORAGE_CONTAINER_ID = VW_STORAGE_RECORD_DETAILED.STORAGE_CONTAINER_ID ',
'                   AND newer_rec.STORAGE_DATE > VW_STORAGE_RECORD_DETAILED.STORAGE_DATE',
'                ) > 0 ',
'               THEN ''pointer-events: none; opacity: 0.5; cursor: default;''',
'           WHEN HOURS_OLD >= 24 ',
'               THEN ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'           WHEN USER_ID != :APP_CURRENT_USER_ID ',
'                AND (SELECT USER_ROLE FROM APP_USER WHERE USER_ID = :APP_CURRENT_USER_ID) != ''Administrator''',
'               THEN ''pointer-events: none; opacity: 0.5; cursor: default;''     ',
'           ELSE '''' ',
'       END as EDIT_STYLE',
'',
'  FROM VW_STORAGE_RECORD_DETAILED',
'  WHERE ',
'    (:P301_WASTE_TYPE_NAME IS NULL ',
'     OR INSTR('':'' || :P301_WASTE_TYPE_NAME || '':'', '':'' || WASTE_TYPE_NAME || '':'') > 0)',
'    ',
'    AND (:P301_STORAGE_LOCATION_NAME IS NULL ',
'         OR INSTR('':'' || :P301_STORAGE_LOCATION_NAME || '':'', '':'' || STORAGE_LOCATION_NAME || '':'') > 0)',
'',
'    AND (:P301_STORAGE_FILL_LEVEL IS NULL ',
'         OR EXISTS (',
'            SELECT 1 FROM TABLE(apex_string.split(:P301_STORAGE_FILL_LEVEL, '':''))',
'            WHERE STORAGE_FILL_LEVEL >= TO_NUMBER(REGEXP_SUBSTR(column_value, ''^[^|]+''))',
'              AND (REGEXP_SUBSTR(column_value, ''[^|]+$'') IS NULL ',
'                   OR STORAGE_FILL_LEVEL < TO_NUMBER(REGEXP_SUBSTR(column_value, ''[^|]+$'')))',
'         ))',
'',
'    AND (:P301_STORAGE_DATE IS NULL ',
'         OR (STORAGE_DATE >= TO_DATE(REGEXP_SUBSTR(:P301_STORAGE_DATE, ''^[^|]+''), ''YYYYMMDDHH24MISS'')',
'             AND (REGEXP_SUBSTR(:P301_STORAGE_DATE, ''[^|]+$'') IS NULL ',
'                  OR STORAGE_DATE <= TO_DATE(REGEXP_SUBSTR(:P301_STORAGE_DATE, ''[^|]+$''), ''YYYYMMDDHH24MISS''))))',
'    ORDER BY STORAGE_RECORD_ID DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P301_WASTE_TYPE_NAME, P301_STORAGE_LOCATION_NAME, P301_STORAGE_FILL_LEVEL, P301_STORAGE_RECORD_DATE'
