'    sc.STORAGE_CONTAINER_CODE || '' - '' || wt.WASTE_TYPE_NAME || ',
'    '' ('' || sl.STORAGE_LOCATION_NAME || '')'' AS display_value,',
'    sc.STORAGE_CONTAINER_ID AS return_value',
