wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(128628559846836660832)
,p_validation_name=>'Check Date Order'
,p_static_id=>'check-date-order'
,p_validation_sequence=>60
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_latest_date DATE;',
'BEGIN',
'    -- 1. Find the LATEST date currently in the database for this specific container',
'    --    We exclude the current record (:P301_STORAGE_RECORD_ID) so that if you are ',
'    --    editing the latest record, it compares against the *second* latest (the one before it).',
'    SELECT MAX(STORAGE_DATE)',
'    INTO v_latest_date',
'    FROM STORAGE_RECORD',
'    WHERE STORAGE_CONTAINER_ID = :P301_STORAGE_CONTAINER_ID',
'      AND (:P301_STORAGE_RECORD_ID IS NULL OR STORAGE_RECORD_ID != :P301_STORAGE_RECORD_ID);',
'',
'    -- 2. Compare: If the date you entered is OLDER than the database date -> ERROR',
'    IF :P301_STORAGE_DATE < v_latest_date THEN',
'        RETURN ''Invalid Date: You cannot backdate this record. The most recent activity for this container was on '' ',
'               || TO_CHAR(v_latest_date, ''DD-Mon-YYYY'') ',
'               || ''. Your date must be after that.'';',
'    END IF;',
'',
'    -- 3. If no issues, return NULL (Validation Passed)',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'CREATE,SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(265058307405929822083)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260119113519Z')
,p_updated_on=>wwv_flow_imp.dz('20260119113519Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
