wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(8737289992686354894)
,p_validation_name=>'Check Quantity Not Exceed Max'
,p_static_id=>'check-quantity-not-exceed-max'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_capacity NUMBER;',
'    v_unit     VARCHAR2(20);',
'BEGIN',
'    -- Get the capacity of the selected container',
'    SELECT STORAGE_CONTAINER_CAPACITY, STORAGE_CONTAINER_UNIT',
'    INTO v_capacity, v_unit',
'    FROM STORAGE_CONTAINER',
'    WHERE STORAGE_CONTAINER_ID = :P302_STORAGE_CONTAINER_ID;',
'',
'    -- Compare input vs capacity',
'    IF :P302_STORAGE_CURRENT_QUANTITY > v_capacity THEN',
'        RETURN ''Error: You entered '' || :P302_STORAGE_CURRENT_QUANTITY || ',
'               '' but the maximum capacity is '' || v_capacity || '' '' || v_unit || ''.'';',
'    END IF;',
'',
'    RETURN NULL; -- Returning NULL means "No Error, Validation Passed"',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN NULL; -- Skip validation if container isn''t selected yet',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'CREATE,SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(261214799852843147512)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260115142327Z')
,p_updated_on=>wwv_flow_imp.dz('20260119113557Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(8685090622624851233)
,p_validation_name=>'Validate Storage Increase Rules'
,p_static_id=>'validate-storage-increase-rules'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    -- 1. DEFINE VARIABLES',
'    V_CONTAINER_ID        STORAGE_RECORD.STORAGE_CONTAINER_ID%TYPE; -- Uses the type from your table',
'    V_UNIT                VARCHAR2(20); -- To hold ''kg'', ''Liters'', etc.',
'    V_CAPACITY            NUMBER;',
'    V_PREV_QTY            NUMBER;',
'    V_PREV_FILL_PCT       NUMBER;',
'    V_NEW_QTY             NUMBER;',
'    ',
'BEGIN',
'    -------------------------------------------------------------------------',
'    -- 2. SAFE INPUT ASSIGNMENT',
'    -------------------------------------------------------------------------',
'    -- Container ID is VARCHAR2 based on your table definition',
'    V_CONTAINER_ID := :P302_STORAGE_CONTAINER_ID; ',
'    V_NEW_QTY      := TO_NUMBER(:P302_STORAGE_CURRENT_QUANTITY);',
'',
'    -- Basic Null Checks',
'    IF V_CONTAINER_ID IS NULL THEN',
'        RETURN ''Error: Please select a Storage Container.'';',
'    END IF;',
'    ',
'    IF V_NEW_QTY IS NULL THEN',
'        RETURN ''Error: Quantity is required.'';',
'    END IF;',
'',
'    -------------------------------------------------------------------------',
'    -- 3. SECURITY CHECK',
'    -------------------------------------------------------------------------',
'    FOR R IN (SELECT USER_ROLE FROM APP_USER WHERE USER_ID = :APP_CURRENT_USER_ID) LOOP',
'        IF R.USER_ROLE = ''SYSTEM'' THEN RETURN NULL; END IF;',
'    END LOOP;',
'',
'    -------------------------------------------------------------------------',
'    -- 4. FETCH CAPACITY & UNIT FROM PARENT TABLE',
'    -------------------------------------------------------------------------',
'    BEGIN',
'        -- CHANGE ''STORAGE_UNIT'' below to your actual column name in STORAGE_CONTAINER table!',
'        SELECT STORAGE_CONTAINER_CAPACITY, STORAGE_CONTAINER_UNIT ',
'        INTO V_CAPACITY, V_UNIT',
'        FROM STORAGE_CONTAINER ',
'        WHERE STORAGE_CONTAINER_ID = V_CONTAINER_ID;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN RETURN ''Error: Invalid Container ID selected.'';',
'    END;',
'    ',
'    -- Safety check if capacity is missing',
'    IF V_CAPACITY IS NULL OR V_CAPACITY = 0 THEN',
'        RETURN ''Configuration Error: Selected container has a capacity of 0.'';',
'    END IF;',
'',
'    -------------------------------------------------------------------------',
'    -- 5. COMPARE WITH PREVIOUS RECORD (CORRECTED)',
'    -------------------------------------------------------------------------',
'    BEGIN',
'        SELECT STORAGE_CURRENT_QUANTITY ',
'        INTO V_PREV_QTY',
'        FROM STORAGE_RECORD',
'        WHERE STORAGE_CONTAINER_ID = V_CONTAINER_ID',
'          -- CRITICAL FIX: Exclude the record currently being edited',
'          AND (:P302_STORAGE_RECORD_ID IS NULL OR STORAGE_RECORD_ID != :P302_STORAGE_RECORD_ID)',
'        ORDER BY STORAGE_RECORD_CREATED_DATE DESC',
'        FETCH FIRST 1 ROW ONLY;',
'        ',
'        -- Calculate % for the "80% Full" Rule',
'        V_PREV_FILL_PCT := ROUND((V_PREV_QTY / V_CAPACITY) * 100, 2);',
'',
'        -- CHECK A: Is the *previous* record already too full?',
'        -- (Only applies if we are adding a NEW record on top of a full one)',
'        IF V_PREV_FILL_PCT >= 80 THEN',
'            RETURN ''Container Alert: Previous level was '' || V_PREV_FILL_PCT || ''%. This container is awaiting disposal.'';',
'        END IF;',
'',
'        -- CHECK B: Must Increase Rule',
'        IF V_NEW_QTY <= V_PREV_QTY THEN',
'            RETURN ''Invalid Entry: Quantity ('' || V_NEW_QTY || '' '' || V_UNIT || ',
'                   '') must be higher than the previous record ('' || V_PREV_QTY || '' '' || V_UNIT || '').'';',
'        END IF;',
'',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN ',
'            -- If no previous record exists (or we are editing the very first one),',
'            -- allow any value (even 0 if that''s valid for your app).',
'            RETURN NULL; ',
'    END;',
'',
'    RETURN NULL;',
'',
'EXCEPTION',
'    WHEN OTHERS THEN RETURN ''System Error: '' || SQLERRM;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'CREATE,SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_associated_item=>wwv_flow_imp.id(261214799852843147512)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260115145845Z')
,p_updated_on=>wwv_flow_imp.dz('20260119113519Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
