'       STORAGE_CONTAINER_CODE,',
'       STORAGE_CONTAINER_CAPACITY || '' '' || STORAGE_CONTAINER_UNIT AS "Capacity",',
'       STORAGE_CONTAINER_STATUS,',
'       WASTE_TYPE_ID,',
'       STORAGE_LOCATION_ID,',
'       '' '' AS EDIT_LINK',
'  from STORAGE_CONTAINER',
'  WHERE (:P303_STORAGE_LOCATION_ID IS NULL ',
'       OR INSTR('':'' || :P303_STORAGE_LOCATION_ID || '':'', '':'' || STORAGE_LOCATION_ID || '':'') > 0)',
