wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(128628560214897660836)
,p_validation_name=>'Check Capacity Shrinkage'
,p_static_id=>'check-capacity-shrinkage'
,p_validation_sequence=>80
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_old_capacity NUMBER;',
'BEGIN',
'    -- Only run this check if we are EDITING an existing container',
'    IF :P304_STORAGE_CONTAINER_ID IS NOT NULL THEN',
'        ',
'        -- Get the old capacity from the database',
'        SELECT STORAGE_CONTAINER_CAPACITY',
'        INTO v_old_capacity',
'        FROM STORAGE_CONTAINER',
'        WHERE STORAGE_CONTAINER_ID = :P304_STORAGE_CONTAINER_ID;',
'',
'        -- CHECK: Is the New Capacity smaller than the Old one?',
'        IF :P304_STORAGE_CONTAINER_CAPACITY < v_old_capacity THEN',
'            RETURN ''Invalid Action: You cannot decrease the capacity of an existing container. '' ||',
'                   ''Current: '' || v_old_capacity || '', New: '' || :P304_STORAGE_CONTAINER_CAPACITY || ',
'                   ''. If this is a mistake, please contact an Administrator.'';',
'        END IF;',
'',
'    END IF;',
'',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(3961463902127373436)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
