wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(128628560166400660835)
,p_validation_name=>'Check Fill Status Consistency'
,p_static_id=>'check-fill-status-consistency'
,p_validation_sequence=>70
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_latest_qty      NUMBER;',
'    v_capacity        NUMBER;',
'    v_fill_percent    NUMBER;',
'BEGIN',
'    -- 1. Get the latest Quantity from the Record AND Capacity from the Container',
'    -- We join the tables to get both numbers at once.',
'    BEGIN',
'        SELECT SR.STORAGE_CURRENT_QUANTITY, SC.STORAGE_CONTAINER_CAPACITY',
'        INTO v_latest_qty, v_capacity',
'        FROM STORAGE_RECORD SR',
'        JOIN STORAGE_CONTAINER SC ON SR.STORAGE_CONTAINER_ID = SC.STORAGE_CONTAINER_ID',
'        WHERE SR.STORAGE_CONTAINER_ID = :P304_STORAGE_CONTAINER_ID',
'        ORDER BY SR.STORAGE_DATE DESC',
'        FETCH FIRST 1 ROW ONLY;',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN ',
'            -- No records exist? Assume 0% full.',
'            v_latest_qty := 0;',
'            v_capacity   := 1; -- Avoid divide-by-zero',
'    END;',
'',
'    -- 2. Calculate the Percentage',
'    IF v_capacity > 0 THEN',
'        v_fill_percent := (v_latest_qty / v_capacity) * 100;',
'    ELSE',
'        v_fill_percent := 0;',
'    END IF;',
'',
'    -- 3. THE CHECK: ',
'    -- If calculated fill is 80% or more, BLOCK changing status to ''Available''',
'    IF v_fill_percent >= 80 AND :P304_STORAGE_CONTAINER_STATUS = ''Available'' THEN',
'        RETURN ''Consistency Error: This container is effectively '' || ROUND(v_fill_percent, 1) || ',
'               ''% full based on the latest record ('' || v_latest_qty || '' / '' || v_capacity || ''). You cannot mark it as "Available" until it is emptied.'';',
'    END IF;',
'',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(3961463902127373436)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260119123556Z')
,p_updated_on=>wwv_flow_imp.dz('20260119123556Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(128628560036406660834)
,p_validation_name=>'Check Location Capacity'
,p_static_id=>'check-location-capacity'
,p_validation_sequence=>60
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_status   VARCHAR2(20);',
'    v_loc_name VARCHAR2(100);',
'    v_old_loc_id STORAGE_CONTAINER.STORAGE_LOCATION_ID%TYPE;',
'BEGIN',
'    -- 1. Get the Status and Name of the location the user selected',
'    SELECT STORAGE_LOCATION_STATUS, STORAGE_LOCATION_NAME',
'    INTO v_status, v_loc_name',
'    FROM STORAGE_LOCATION',
'    WHERE STORAGE_LOCATION_ID = :P304_STORAGE_LOCATION_ID;',
'',
'    -- 2. If the location is marked ''Full'', we need to check if we should block it.',
'    IF v_status = ''Full'' THEN',
'        ',
'        -- EDGE CASE CHECK: Are you just editing a container that is ALREADY in this room?',
'        -- If yes, we should let you save (e.g., renaming the container).',
'        -- We only block you if you are NEW or MOVING INTO this full room.',
'        ',
'        IF :P304_STORAGE_CONTAINER_ID IS NOT NULL THEN',
'             SELECT STORAGE_LOCATION_ID ',
'             INTO v_old_loc_id',
'             FROM STORAGE_CONTAINER ',
'             WHERE STORAGE_CONTAINER_ID = :P304_STORAGE_CONTAINER_ID;',
'',
'             -- If the location hasn''t changed, you are safe. Return NULL (Success).',
'             IF v_old_loc_id = :P304_STORAGE_LOCATION_ID THEN',
'                 RETURN NULL; ',
'             END IF;',
'        END IF;',
'',
'        -- 3. If we reached here, you are trying to enter a full room. Block it.',
'        RETURN ''Selection Error: The location "'' || v_loc_name || ''" is currently at full capacity. Please choose a different storage location.'';',
'    END IF;',
'',
'    RETURN NULL;',
'',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN ',
'        RETURN NULL; -- Should not happen, but safe to ignore.',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'CREATE,SAVE'
,p_validation_condition_type=>'REQUEST_IN_CONDITION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20260119121151Z')
,p_updated_on=>wwv_flow_imp.dz('20260119121151Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(128628559926309660833)
,p_validation_name=>'Check Parent Location Status'
,p_static_id=>'check-parent-location-status'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_loc_status VARCHAR2(20);',
'BEGIN',
'    -- 1. Check the Parent Location''s Status',
'    SELECT STORAGE_LOCATION_STATUS',
'    INTO v_loc_status',
'    FROM STORAGE_LOCATION',
'    WHERE STORAGE_LOCATION_ID = :P304_STORAGE_LOCATION_ID; -- Ensure this matches your Item Name',
'',
'    -- 2. If Parent is ''Out of Service'', BLOCK changes',
'    IF v_loc_status = ''Out of Service'' THEN',
'        -- Allow the save ONLY if the user is NOT trying to change the status',
'        -- (i.e., if they are just editing the description, it might be okay, ',
'        -- but usually we lock the whole record).',
'        ',
'        -- To strictly lock the STATUS field:',
'        IF :P304_STORAGE_CONTAINER_STATUS != ''Out of Service'' THEN',
'            RETURN ''Action Blocked: The Storage Location is currently Out of Service. You cannot change the container status until the location is fixed.'';',
'        END IF;',
'    END IF;',
'',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN RETURN NULL; -- Should not happen if ID is valid',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(3961463902127373436)
