wwv_flow_imp_page.create_jet_chart_series(
 p_id=>wwv_flow_imp.id(3991305920907319763)
,p_chart_id=>wwv_flow_imp.id(3991305881532319762)
,p_static_id=>'series'
,p_seq=>10
,p_name=>'Series 1'
,p_data_source_type=>'SQL'
,p_data_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    DISPOSAL_STATUS, ',
'    COUNT(*) AS COUNT,',
'    ',
'    -- COLOR LOGIC',
'    CASE DISPOSAL_STATUS',
'        WHEN ''Completed''   THEN ''#3fb449'' -- Green',
'        WHEN ''Scheduled''   THEN ''#fdbd2c'' -- Orange',
'        ELSE ''#a0a0a0''',
'    END AS STATUS_COLOR,',
'',
'    -- LINK LOGIC (Security + Redirect)',
'    CASE ',
'        -- 1. FIRST, CHECK PERMISSION',
'        -- (Only Admins and Disposal Staff get a link; everyone else gets NULL)',
'        WHEN EXISTS (',
'            SELECT 1 FROM APP_USER ',
'            WHERE UPPER(USERNAME) = UPPER(:APP_USER) ',
'            AND USER_ROLE IN (''Administrator'', ''Disposal Staff'')',
'        ) THEN ',
'            -- 2. IF AUTHORIZED, CHOOSE THE PAGE',
'            CASE DISPOSAL_STATUS',
'                WHEN ''Scheduled'' THEN ''f?p=''||:APP_ID||'':404:''||:APP_SESSION||''::NO:::''',
'                WHEN ''Completed'' THEN ''f?p=''||:APP_ID||'':406:''||:APP_SESSION||''::NO:::''',
'                ELSE NULL',
'            END',
'        ELSE NULL -- Unauthorized users get NO link',
'    END AS LINK_URL',
'',
'FROM DISPOSAL_SCHEDULE',
'WHERE TRUNC(DISPOSAL_DATE) = TRUNC(SYSDATE)',
'GROUP BY DISPOSAL_STATUS;'))
,p_items_value_column_name=>'COUNT'
,p_items_label_column_name=>'DISPOSAL_STATUS'
,p_color=>'&STATUS_COLOR.'
,p_items_label_rendered=>true
,p_items_label_position=>'auto'
,p_items_label_display_as=>'LABEL'
,p_threshold_display=>'onIndicator'
,p_link_target=>'&LINK_URL.'
,p_link_target_type=>'REDIRECT_URL'
,p_created_on=>wwv_flow_imp.dz('20251228080507Z')
,p_updated_on=>wwv_flow_imp.dz('20260116025131Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(8685091374125851240)
,p_name=>'Disposal Alerts'
,p_static_id=>'disposal-alerts'
,p_title=>'Disposal Alerts'
,p_template=>4072358936313175081
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH USER_AUTH AS (',
'    -- 1. SECURITY CHECK',
'    -- Returns ''Y'' if the user is an Admin or Disposal Staff, otherwise ''N''',
'    SELECT CASE ',
'        WHEN EXISTS (',
'            SELECT 1 ',
'            FROM APP_USER ',
'            WHERE UPPER(USERNAME) = UPPER(:APP_USER) ',
'            AND USER_ROLE IN (''Administrator'', ''Disposal Staff'')',
'        ) THEN ''Y'' ',
'        ELSE ''N'' ',
'    END AS IS_AUTHORIZED',
'    FROM DUAL',
')',
'',
'/* ALERT 1: REQUIRE DISPOSAL -> Page 401 */',
'SELECT ',
'    ''Action Required: '' || sc.STORAGE_CONTAINER_CODE AS ALERT_TITLE,',
'    ''Container is '' || ROUND(sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100, 0) || ''% full.'' AS ALERT_DESC,',
'    ''warning''                  AS ALERT_TYPE,',
'    ''fa-exclamation-circle''    AS ALERT_ICON,',
'    ',
'    -- AUTHENTICATION LOGIC:',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN APEX_PAGE.GET_URL(p_page => ''401'')  -- Generate Link if Admin',
'         ELSE ''javascript:void(0);''               -- Dead Link if not',
'    END AS ALERT_LINK,',
'    ',
'    NULL                       AS ALERT_ACTION,',
'    1 AS SORT_ORDER',
'FROM STORAGE_RECORD sr',
'JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'WHERE sr.STORAGE_RECORD_ID IN (SELECT MAX(STORAGE_RECORD_ID) FROM STORAGE_RECORD GROUP BY STORAGE_CONTAINER_ID)',
'  AND (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 80',
'  AND NOT EXISTS (',
'      SELECT 1 FROM DISPOSAL_SCHEDULE ds ',
'      WHERE ds.STORAGE_RECORD_ID = sr.STORAGE_RECORD_ID ',
'      AND ds.DISPOSAL_STATUS IN (''Scheduled'', ''In Progress'')',
'  )',
'',
'UNION ALL',
'',
'/* ALERT 2: SCHEDULED FOR TODAY -> Page 404 */',
'SELECT ',
'    ''Scheduled Pickup: '' || sc.STORAGE_CONTAINER_CODE AS ALERT_TITLE,',
'    ''Disposal scheduled for today.'' AS ALERT_DESC,',
'    ''info''                     AS ALERT_TYPE,',
'    ''fa-clock-o''               AS ALERT_ICON,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN APEX_PAGE.GET_URL(p_page => ''404'') ',
'         ELSE ''javascript:void(0);'' ',
'    END AS ALERT_LINK,',
'    ',
'    NULL                       AS ALERT_ACTION,',
'    2 AS SORT_ORDER',
'FROM DISPOSAL_SCHEDULE ds',
'JOIN STORAGE_RECORD sr ON ds.STORAGE_RECORD_ID = sr.STORAGE_RECORD_ID',
'JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'WHERE TRUNC(ds.DISPOSAL_DATE) = TRUNC(SYSDATE)',
'  AND ds.DISPOSAL_STATUS = ''Scheduled''',
'',
'UNION ALL',
'',
'/* ALERT 3: COMPLETED TODAY -> Page 406 */',
'SELECT ',
'    ''Disposal Completed: '' || sc.STORAGE_CONTAINER_CODE AS ALERT_TITLE,',
'    ''Successfully disposed.''   AS ALERT_DESC,',
'    ''success''                  AS ALERT_TYPE,',
'    ''fa-check-circle''          AS ALERT_ICON,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN APEX_PAGE.GET_URL(p_page => ''406'') ',
'         ELSE ''javascript:void(0);'' ',
'    END AS ALERT_LINK,',
'',
'    NULL                       AS ALERT_ACTION,',
'    3 AS SORT_ORDER',
'FROM DISPOSAL_SCHEDULE ds',
'JOIN STORAGE_RECORD sr ON ds.STORAGE_RECORD_ID = sr.STORAGE_RECORD_ID',
'JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'JOIN DISPOSAL_CONTRACTOR c ON ds.DISPOSAL_CONTRACTOR_ID = c.DISPOSAL_CONTRACTOR_ID',
'JOIN DISPOSAL_METHOD dm ON c.DISPOSAL_METHOD_ID = dm.DISPOSAL_METHOD_ID',
'WHERE TRUNC(ds.COMPLETION_DATE) = TRUNC(SYSDATE)',
'  AND ds.DISPOSAL_STATUS = ''Completed'';'))
,p_ajax_enabled=>'Y'
,p_fixed_header=>'PAGE'
,p_lazy_loading=>false
,p_query_row_template=>2882902941739462796
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_num_rows_type=>'SHOW_ALL'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260116025856Z')
,p_updated_on=>wwv_flow_imp.dz('20260116034124Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
