wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3991305559656319759)
,p_plug_name=>'Disposal Schedule Overview'
,p_static_id=>'disposal-schedule-overview'
,p_region_template_options=>'t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleA'
,p_plug_template=>2072724515482255512
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'WITH USER_AUTH AS (',
'    SELECT CASE ',
'        WHEN EXISTS (',
'            SELECT 1 ',
'            FROM APP_USER ',
'            WHERE USERNAME = :APP_USER ',
'            AND USER_ROLE IN (''Administrator'', ''Disposal Staff'') ',
'        ) THEN ''Y'' ',
'        ELSE ''N'' ',
'    END AS IS_AUTHORIZED',
'    FROM DUAL',
')',
'',
'/* CARD 1: DISPOSAL REQUIRED */',
'SELECT ',
'    ''Disposal Required'' AS CARD_TITLE,',
'    ',
'    -- FORCE STYLE HERE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (',
'        SELECT COUNT(*)',
'        FROM STORAGE_RECORD sr',
'        JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'        WHERE sr.STORAGE_RECORD_ID IN (SELECT MAX(STORAGE_RECORD_ID) FROM STORAGE_RECORD GROUP BY STORAGE_CONTAINER_ID)',
'          AND (sr.STORAGE_CURRENT_QUANTITY / sc.STORAGE_CONTAINER_CAPACITY * 100) >= 80',
'          AND NOT EXISTS (',
'              SELECT 1 FROM DISPOSAL_SCHEDULE ds ',
'              WHERE ds.STORAGE_RECORD_ID = sr.STORAGE_RECORD_ID ',
'              AND ds.DISPOSAL_STATUS IN (''Scheduled'')',
'          )',
'    ) ',
'    || ''</span>''               AS CARD_VALUE,',
'    ',
'    ''fa fa-exclamation-triangle'' AS CARD_ICON,',
'    ''u-color-1''                AS CARD_COLOR,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN APEX_PAGE.GET_URL(p_page => ''401'') ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN ''my-hover-card'' ',
'         ELSE ''my-locked-card'' ',
'    END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 2: SCHEDULED TODAY */',
'SELECT ',
'    ''Scheduled Today''          AS CARD_TITLE,',
'    ',
'    -- FORCE STYLE HERE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) FROM DISPOSAL_SCHEDULE WHERE DISPOSAL_STATUS = ''Scheduled'' AND TRUNC(DISPOSAL_DATE) = TRUNC(SYSDATE)) ',
'    || ''</span>''               AS CARD_VALUE,',
'    ',
'    ''fa fa-clock-o''            AS CARD_ICON,',
'    ''u-color-7''                AS CARD_COLOR,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':404:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' THEN ''my-hover-card'' ELSE ''my-locked-card'' END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 3: TOTAL CONTRACTORS */',
'SELECT ',
'    ''Total Contractors''        AS CARD_TITLE,',
'    ',
'    -- FORCE STYLE HERE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) FROM DISPOSAL_CONTRACTOR) ',
'    || ''</span>''               AS CARD_VALUE,',
'    ',
'    ''fa fa-users''              AS CARD_ICON,',
'    ''u-color-9''                AS CARD_COLOR,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':410:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' THEN ''my-hover-card'' ELSE ''my-locked-card'' END AS CARD_CLASS',
'FROM DUAL',
'',
'UNION ALL',
'',
'/* CARD 4: TOTAL METHODS */',
'SELECT ',
'    ''Total Methods''            AS CARD_TITLE,',
'    ',
'    -- FORCE STYLE HERE --',
'    ''<span style="font-size: 1.5rem; font-weight: 700; display: block; text-align: center; line-height: 1.2;">'' ',
'    || (SELECT COUNT(*) FROM DISPOSAL_METHOD) ',
'    || ''</span>''               AS CARD_VALUE,',
'    ',
'    ''fa fa-flask''              AS CARD_ICON,',
'    ''u-color-4''                AS CARD_COLOR,',
'    ',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' ',
'         THEN ''f?p=''||:APP_ID||'':408:''||:APP_SESSION||''::NO:::'' ',
'         ELSE NULL ',
'    END AS CARD_LINK,',
'',
'    CASE WHEN (SELECT IS_AUTHORIZED FROM USER_AUTH) = ''Y'' THEN ''my-hover-card'' ELSE ''my-locked-card'' END AS CARD_CLASS',
'FROM DUAL;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20251228051617Z')
,p_updated_on=>wwv_flow_imp.dz('20260116125105Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
