,p_escape_on_http_output=>'N'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    STORAGE_RECORD_ID, ',
'    DISPOSAL_SCHEDULE_ID,',
'    STORAGE_CONTAINER_CODE AS "Container", ',
'    STORAGE_LOCATION_NAME AS "Location", ',
'    WASTE_TYPE_NAME AS "Waste Type", ',
'    STORAGE_CURRENT_QUANTITY || '' '' || STORAGE_CONTAINER_UNIT AS "Current Quantity", ',
'    STORAGE_FILL_LEVEL || ''%'' AS "Fill Level", ',
'    FILL_STATUS AS "Alert Level", ',
'    ACTION_STATUS AS "Status", ',
'    CASE  ',
'        -- SCENARIO 1: Create New Schedule',
'        WHEN DISPOSAL_STATUS = ''Not Scheduled'' THEN ',
'            ''<a href="'' || APEX_UTIL.PREPARE_URL(',
'                ''f?p='' || :APP_ID || '':403:'' || :APP_SESSION ||  ',
'                ''::::P403_STORAGE_RECORD_ID,P403_DISPOSAL_SCHEDULE_ID:'' || ',
'                STORAGE_RECORD_ID || '','' || '''' -- Pass ID + Empty Value',
'            ) ||  ',
'            ''" class="t-Button t-Button--hot t-Button--simple t-Button--small">',
'            <span class="fa fa-calendar-plus"></span> Schedule Disposal</a>'' ',
'',
'        -- SCENARIO 2: View/Edit Existing Schedule',
'        WHEN DISPOSAL_STATUS = ''Scheduled'' THEN ',
'            ''<a href="'' || APEX_UTIL.PREPARE_URL(',
'                ''f?p='' || :APP_ID || '':403:'' || :APP_SESSION ||  ',
'                ''::::P403_STORAGE_RECORD_ID,P403_DISPOSAL_SCHEDULE_ID:'' || ',
'                STORAGE_RECORD_ID || '','' || DISPOSAL_SCHEDULE_ID -- Pass Both IDs',
'            ) ||  ',
'            ''" style="text-decoration: none;">'' || -- Wrap the badge in a link',
unistr('            ''<span class="t-Badge t-Badge--success t-Badge--interactive">\2705 Scheduled by '' ||  '),
'            SCHEDULED_BY || '' for '' || TO_CHAR(SCHEDULED_DATE, ''DD-MON'') || ''</span></a>'' ',
'        ELSE ',
unistr('            ''\2014'' '),
'    END AS "Action", ',
'    DISPOSAL_STATUS, ',
'    SCHEDULED_BY, ',
'    SCHEDULED_DATE ',
'FROM VW_STORAGE_ALERT_FOR_DISPOSAL ',
'WHERE DISPOSAL_STATUS IN (''Not Scheduled'', ''Scheduled'') ',
'ORDER BY  ',
'    CASE  ',
'        WHEN DISPOSAL_STATUS = ''Not Scheduled'' AND STORAGE_FILL_LEVEL >= 95 THEN 1 ',
'        WHEN DISPOSAL_STATUS = ''Not Scheduled'' AND STORAGE_FILL_LEVEL >= 80 THEN 2 ',
'        WHEN DISPOSAL_STATUS = ''Scheduled'' THEN 3 ',
'        ELSE 4 ',
'    END, ',
'    STORAGE_FILL_LEVEL DESC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_page_header=>'Disposal Alert List'
