wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4042547894781916446)
,p_plug_name=>'Disposal Schedule IR (based on View)'
,p_static_id=>'disposal-schedule-ir-based-on-view'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>20
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT ',
'    DISPOSAL_SCHEDULE_ID,',
'    TO_CHAR(DISPOSAL_DATE, ''DD-MON-YYYY'') AS "Disposal Date",',
'    STORAGE_CONTAINER_CODE AS "Container",',
'    WASTE_TYPE_NAME AS "Waste Type",',
'    QUANTITY_DISPOSED || '' kg/L'' AS "Quantity",',
'    METHOD_NAME AS "Method",',
'    CONTRACTOR_NAME AS "Contractor",',
'    DISPOSAL_STATUS AS "Status",',
'    SCHEDULED_BY AS "Scheduled By",',
'    ',
'    -- 1. ICON COLOR LOGIC',
'    -- If Completed -> Red (Disabled look)',
'    -- Else -> Blue (Editable look)',
'    CASE ',
'        WHEN DISPOSAL_STATUS = ''Completed'' THEN ''u-danger-text''',
'        ELSE ''u-info-text''',
'    END AS ICON_COLOR,',
'',
'    -- 2. EDIT STYLE LOGIC (The actual lock)',
'    -- If Completed -> Disable clicking and fade it out',
'    CASE ',
'        WHEN DISPOSAL_STATUS = ''Completed'' THEN ',
'            ''pointer-events: none; opacity: 0.5; cursor: default;'' ',
'        ELSE ''''',
'    END AS EDIT_STYLE,',
'',
'    '' '' AS EDIT_LINK,',
'',
'    CASE ',
'        WHEN COMPLETED_BY_NAME IS NOT NULL THEN COMPLETED_BY_NAME',
'        WHEN COMPLETION_METHOD = ''Auto'' THEN ''System Auto-Complete''',
unistr('        ELSE ''\2014'''),
'    END AS "Completed By"',
'FROM VW_DISPOSAL_SCHEDULE_DETAILS',
'WHERE ',
'    -- 1. Status Facet',
'    (:P402_DISPOSAL_STATUS IS NULL ',
'      OR INSTR('':'' || :P402_DISPOSAL_STATUS || '':'', '':'' || DISPOSAL_STATUS || '':'') > 0)',
'    ',
'    -- 2. Method Facet',
'    AND (:P402_METHOD_NAME IS NULL ',
'          OR INSTR('':'' || :P402_METHOD_NAME || '':'', '':'' || METHOD_NAME || '':'') > 0)',
'    ',
'    -- 3. Contractor Facet',
'    AND (:P402_CONTRACTOR_NAME IS NULL ',
'          OR INSTR('':'' || :P402_CONTRACTOR_NAME || '':'', '':'' || CONTRACTOR_NAME || '':'') > 0)',
'    ',
'    -- 4. Date Range Facet',
'    AND (:P402_DISPOSAL_DATE IS NULL ',
'          OR (DISPOSAL_DATE >= TO_DATE(REGEXP_SUBSTR(:P402_DISPOSAL_DATE, ''^[^|]+''), ''YYYYMMDDHH24MISS'')',
'              AND (REGEXP_SUBSTR(:P402_DISPOSAL_DATE, ''[^|]+$'') IS NULL ',
