wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(4042715775052296553)
,p_validation_name=>'Check Date Disposal After Storage Date'
,p_static_id=>'check-date-disposal-after-storage-date'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_storage_date DATE;',
'    v_disposal_date DATE;',
'BEGIN',
'    -- 1. Get the storage date from the database',
'    SELECT STORAGE_DATE',
'    INTO v_storage_date',
'    FROM STORAGE_RECORD',
'    WHERE STORAGE_RECORD_ID = :P403_STORAGE_RECORD_ID;',
'',
'    -- 2. Convert the item value using the current APEX session format',
'    -- Passing NULL to TO_DATE in APEX logic can sometimes be tricky,',
'    -- so we use V() or simply the bind variable if APEX handles the auto-conversion.',
'    v_disposal_date := TO_DATE(:P403_DISPOSAL_DATE, ',
'                        nvl(v(''APP_DATE_TIME_FORMAT''), v(''APP_DATE_FORMAT'')));',
'',
'    -- 3. Perform the comparison',
'    -- 3. Perform the comparison using TRUNC to ignore time',
'IF TRUNC(v_disposal_date) < TRUNC(v_storage_date) THEN',
'    RETURN ''Disposal date cannot be earlier than the storage record date ('' || ',
'           TO_CHAR(v_storage_date, nvl(v(''APP_DATE_FORMAT''), ''DD-MON-YYYY'')) || '').'';',
'END IF;',
'',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''Error: Associated storage record not found.'';',
'    WHEN OTHERS THEN',
'        -- This will catch format mismatches and show you the actual values',
'        RETURN ''Format Error. Item Value: '' || :P403_DISPOSAL_DATE || ',
'               '' Error: '' || SQLERRM;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_imp.id(4042530496289916429)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_created_on=>wwv_flow_imp.dz('20251228130845Z')
,p_updated_on=>wwv_flow_imp.dz('20260114195330Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
