,p_validation_name=>'Check Quantity Cannot Exceed Current Value'
,p_static_id=>'check-quantity-cannot-exceed-current-value'
,p_validation_sequence=>60
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_available_qty NUMBER;',
'BEGIN',
'    -- Get the current quantity from the storage record',
'    SELECT STORAGE_CURRENT_QUANTITY',
'    INTO v_available_qty',
'    FROM STORAGE_RECORD',
'    WHERE STORAGE_RECORD_ID = :P403_STORAGE_RECORD_ID;',
'',
'    -- Check if the user is trying to dispose of more than what exists',
'    IF :P403_QUANTITY_DISPOSED > v_available_qty THEN',
'        RETURN ''Disposed quantity ('' || :P403_QUANTITY_DISPOSED || ',
'               '') cannot exceed the available quantity in the container ('' || v_available_qty || '').'';',
'    END IF;',
'',
'    RETURN NULL; -- Pass validation',
'EXCEPTION',
'    WHEN NO_DATA_FOUND THEN',
'        RETURN ''Error: Storage record not found.'';',
'END;'))
,p_validation2=>'PLSQL'
