begin
wwv_flow_imp_page.create_page(
 p_id=>404
,p_name=>'Upcoming Schedules'
,p_alias=>'UPCOMING-SCHEDULES'
,p_step_title=>'Upcoming Schedules'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function completeDisposal(checkbox, scheduleId) {',
'    if (checkbox.checked) {',
'        apex.message.confirm("Confirm disposal completion?", function(okPressed) {',
'            if (okPressed) {',
'                apex.server.process("PROCESS_COMPLETION", {',
'                    x01: scheduleId',
'                }, {',
'                    success: function(pData) {',
'    if (pData.success) {',
'        apex.region("upcoming_schedule_report").refresh();',
'    } else {',
'        alert("Database Error: " + pData.message); ',
'        checkbox.checked = false;',
'    }',
'},',
'                    error: function(xhr, status, error) {',
'                        console.log("AJAX Error: " + error);',
'                        checkbox.checked = false;',
'                    }',
'                });',
'            } else {',
'                checkbox.checked = false;',
'            }',
'        });',
'    }',
'}'))
,p_step_template=>4072355960268175073
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(8628779120411876493)
,p_protection_level=>'C'
,p_page_component_map=>'18'
,p_created_on=>wwv_flow_imp.dz('20251228172405Z')
