wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4115532656188918709)
,p_plug_name=>'Upcoming Schedules'
,p_static_id=>'upcoming-schedules'
,p_region_name=>'upcoming_schedule_report'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_escape_on_http_output=>'N'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    ds.DISPOSAL_SCHEDULE_ID,',
'    ''<input type="checkbox"',
'            class="disposal-checkbox"',
'            onclick="completeDisposal(this, '''''' || ds.DISPOSAL_SCHEDULE_ID || '''''')">'' AS "Complete",',
'    -- Timeline Status',
'    CASE ',
unistr('        WHEN TRUNC(ds.DISPOSAL_DATE) = TRUNC(SYSDATE) THEN ''\D83D\DD34 TODAY'''),
unistr('        WHEN TRUNC(ds.DISPOSAL_DATE) = TRUNC(SYSDATE) + 1 THEN ''\D83D\DFE1 TOMORROW'''),
unistr('        ELSE ''\D83D\DCC5 '' || TO_CHAR(ds.DISPOSAL_DATE, ''DD-MON'') || '' ('' || '),
'             TRUNC(ds.DISPOSAL_DATE - SYSDATE) || '' days away)''',
'    END AS "Schedule",',
'    sc.STORAGE_CONTAINER_CODE AS "Container",',
'    wt.WASTE_TYPE_NAME AS "Waste Type",',
'    sl.STORAGE_LOCATION_NAME AS "Location",',
'    ds.QUANTITY_DISPOSED || '' '' || sc.STORAGE_CONTAINER_UNIT AS "Quantity",',
'    dm.METHOD_NAME AS "Method",',
'    dc.COMPANY_NAME AS "Contractor"',
'FROM DISPOSAL_SCHEDULE ds',
'JOIN STORAGE_RECORD sr ON ds.STORAGE_RECORD_ID = sr.STORAGE_RECORD_ID',
'JOIN STORAGE_CONTAINER sc ON sr.STORAGE_CONTAINER_ID = sc.STORAGE_CONTAINER_ID',
'JOIN STORAGE_LOCATION sl ON sc.STORAGE_LOCATION_ID = sl.STORAGE_LOCATION_ID',
'JOIN WASTE_TYPE wt ON sc.WASTE_TYPE_ID = wt.WASTE_TYPE_ID',
'JOIN DISPOSAL_CONTRACTOR dc ON ds.DISPOSAL_CONTRACTOR_ID = dc.DISPOSAL_CONTRACTOR_ID',
'JOIN DISPOSAL_METHOD dm ON dc.DISPOSAL_METHOD_ID = dm.DISPOSAL_METHOD_ID',
'WHERE ds.DISPOSAL_DATE >= TRUNC(SYSDATE) ',
'  AND ds.DISPOSAL_DATE <= TRUNC(SYSDATE) + 7',
'  AND ds.DISPOSAL_STATUS = ''Scheduled''',
'ORDER BY ds.DISPOSAL_DATE ASC, sc.STORAGE_CONTAINER_CODE ASC;'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_headings_type=>'COLON_DELMITED_LIST'
,p_prn_page_header=>'Today''s Disposal Checklist'
,p_ai_enabled=>false
,p_created_on=>wwv_flow_imp.dz('20251228172407Z')
,p_updated_on=>wwv_flow_imp.dz('20260123074331Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
