wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4115673087356292421)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'PROCESS_COMPLETION'
,p_static_id=>'process-completion'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_id VARCHAR2(10);',
'    v_user_name VARCHAR2(100);',
'BEGIN',
'    v_id := apex_application.g_x01;',
'',
'    -- 1. Get the current user''s full name',
'    BEGIN',
'        SELECT USER_FULL_NAME ',
'        INTO v_user_name ',
'        FROM APP_USER ',
'        WHERE USER_ID = :APP_CURRENT_USER_ID; ',
'    EXCEPTION ',
'        WHEN NO_DATA_FOUND THEN ',
'            v_user_name := :APP_USER; -- Fallback to username if not found',
'    END;',
'',
'    -- 2. Update with the dynamic note',
'    UPDATE DISPOSAL_SCHEDULE',
'    SET DISPOSAL_STATUS = ''Completed'',',
'        COMPLETION_DATE = SYSTIMESTAMP,',
'        COMPLETED_BY = :APP_CURRENT_USER_ID,',
'        COMPLETION_METHOD = ''Manual'',',
'        COMPLETION_NOTES = ''Manually completed by '' || v_user_name',
'    WHERE DISPOSAL_SCHEDULE_ID = v_id;',
'',
'    COMMIT;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', true);',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''success'', false);',
'        apex_json.write(''message'', SQLERRM); ',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>124059140591574102003
,p_created_on=>wwv_flow_imp.dz('20251228173533Z')
,p_updated_on=>wwv_flow_imp.dz('20260123074140Z')
,p_created_by=>'ALVINTEH0817@STUDENT.USM.MY'
,p_updated_by=>'ALVINTEH0817@STUDENT.USM.MY'
);
end;
