'BEGIN',
'    DELETE FROM DISPOSAL_CONTRACTOR',
'    WHERE DISPOSAL_CONTRACTOR_ID = :P411_DISPOSAL_CONTRACTOR_ID;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        -- Integrity constraint check for child records in DISPOSAL_SCHEDULE',
'        IF SQLCODE = -2292 THEN',
'            RAISE_APPLICATION_ERROR(-20001, ''Cannot delete: This contractor is linked to existing disposal records.'');',
'        ELSE',
'            RAISE;',
'        END IF;',
'END;'))
