wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2803972127944468440)
,p_validation_name=>'Check Role and Department Match'
,p_static_id=>'check-role-and-department-match'
,p_validation_sequence=>130
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_role VARCHAR2(50) := :P9998_USER_ROLE;',
'    v_dept VARCHAR2(50) := :P9998_DEPARTMENT;',
'BEGIN',
'    IF v_role = ''Administrator'' AND v_dept != ''Administration'' THEN',
'        RETURN ''Administrators must be in the Administration department.'';',
'    END IF;',
'    ',
'    IF v_role = ''Waste Management Staff'' AND v_dept = ''Administration'' THEN',
'        RETURN ''Waste Management Staff cannot be in the Administration department.'';',
'    END IF;',
'    ',
'    RETURN NULL;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_associated_item=>wwv_flow_imp.id(3012557723473208339)
